import{_ as s,o as a,c as t,X as i}from"./chunks/framework.6lxT3esk.js";const k=JSON.parse('{"title":"Documentation development","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/docs/contributing.md","filePath":"contributing.md"}'),n={name:"rust/docs/contributing.md"};function o(r,e,d,l,h,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="documentation-development" tabindex="-1">Documentation development <a class="header-anchor" href="#documentation-development" aria-label="Permalink to &quot;Documentation development&quot;">​</a></h1><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><p>This website has an English Rust manual at <code>/rust/</code> and a Python manual at <code>/python/</code>, under one CellPack project homepage. VitePress 1.6.4 renders the manual and landing page. Its theme extension supplies the homepage, typography, navigation and logo player, while VitePress supplies local search, page outlines, syntax highlighting, and code copying.</p><p>Authored guides and module contracts are ordinary Markdown files in this directory. <code>reference.py</code> derives the public interface pages and catalogs from rustdoc. <code>examples/</code> is an independent Cargo package whose Rust sources are included directly in guide pages.</p><table tabindex="0"><thead><tr><th>File or directory</th><th>Purpose</th></tr></thead><tbody><tr><td><code>.vitepress/config.mjs</code></td><td>Site navigation, search, deployment base and build paths</td></tr><tr><td><code>package.json / package-lock.json</code></td><td>Pinned VitePress frontend dependencies</td></tr><tr><td><code>pyproject.toml / uv.lock</code></td><td>Python tools for API generation</td></tr><tr><td><code>build.py</code></td><td>Rustdoc, API generation, example validation and site build</td></tr><tr><td><code>reference.py</code></td><td>Declarations, member indexes, parameters, returns and field documentation</td></tr><tr><td><code>_catalog/</code></td><td>Generated module catalogs and sidebar metadata</td></tr><tr><td><code>generated-*.md</code></td><td>Generated public-interface pages</td></tr><tr><td><code>_build/rustdoc/</code></td><td>Private compiler output used to extract API metadata</td></tr><tr><td><code>_build/html/</code></td><td>Complete static website</td></tr></tbody></table><p>The Python bindings are not installed or imported to build this manual.</p><p>The canonical brand asset is <code>assets/logo.svg</code> at the repository root. The build copies it to the public directory for the navbar, homepage illustration, and browser icon. Update that source asset instead of editing a generated copy.</p><p><code>assets/cellpack-animation.svg</code> supplies the homepage animation. A small default-theme extension in <code>.vitepress/theme/</code> adds its player and navbar hover feedback. The player runs once, supports pause/replay, pauses outside the viewport or in background tabs, and falls back to the static logo for reduced-motion preferences.</p><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>From the repository root, on a machine where compilation is allowed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.96.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minimal</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RUSTUP_TOOLCHAIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1.96.0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/build.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check-examples</span></span></code></pre></div><p>The build generates version-matched rustdoc, refreshes the public-interface catalog, runs every complete guide program when requested, and builds the website with VitePress. Missing document links fail the frontend build. Rustdoc warnings also fail the build.</p><p>Open <code>docs/cellpack/_build/html/index.html</code> through a local web server. For example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/_build/html</span></span></code></pre></div><p>When previewing on a remote compute node, forward that port through your SSH connection. Follow your environment&#39;s proxy and compute-node rules for package installation, compilation, and browser checks.</p><h2 id="live-editing" tabindex="-1">Live editing <a class="header-anchor" href="#live-editing" aria-label="Permalink to &quot;Live editing&quot;">​</a></h2><p>Prepare generated content, then start the VitePress development server:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RUSTUP_TOOLCHAIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1.96.0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/build.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prepare-only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span></span></code></pre></div><p>Markdown edits refresh automatically. After changing Rust public interfaces or their documentation, run the preparation step again. <code>--site-only</code> renders already prepared content; <code>--output</code> selects another HTML directory; <code>--base /en/latest/</code> builds for a URL prefix.</p><h2 id="authoring" tabindex="-1">Authoring <a class="header-anchor" href="#authoring" aria-label="Permalink to &quot;Authoring&quot;">​</a></h2><p>Use ordinary Markdown links for manual pages. The API generator produces the searchable interface pages and links directly between them. Compiler output remains private to the build. Edit Rust documentation and module contracts rather than generated files.</p><p>VitePress includes Rust source directly with <code>&lt;&lt;&lt; @/examples/quickstart.rs</code>.</p><p>Use <code>&lt;DocDiagram name=&quot;…&quot; /&gt;</code> for authored workflow diagrams, identity maps, matrix fixtures and decision cards. Their shared content is in <code>.vitepress/theme/components/doc-diagrams.mjs</code>; <code>DocDiagram.vue</code> renders it with theme colors and responsive layouts. Keep parameter tables, executable source and actual terminal output in Markdown. Edit authored pages rather than generated API declarations or <code>_catalog</code> files.</p><p>Use <code>DocChoices</code> when readers need to choose between interfaces. Put the task in <code>when</code>, the API or path name in <code>label</code>, and the deciding constraint in <code>detail</code>; an optional <code>href</code> links to its canonical documentation URL. It uses the existing theme, supports keyboard focus, and stacks cards on small screens. Keep the number of choices small enough to compare in one reading.</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DocChoices</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Choose a reading path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">items</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { label: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Store&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, when: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Read a selected matrix&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, detail: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Decode on demand.&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, href: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/python/docs/storage.html&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { label: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ScDataLoader&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, when: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Iterate training batches&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, detail: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Choose sample order and output columns.&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, href: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/python/docs/dataloader.html&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>Guides should take readers from a stated input to an observable result. API pages should lead with interface choices and the contracts needed to call them, then expose exact declarations under a clearly named disclosure. Keep essential ownership and error rules visible. Use ordinary headings for subjects readers need to link to; avoid hiding the entire tutorial in cards or disclosures. Python module API outlines show authored level-two sections. Generated symbols use level-three headings, with members at level four, inside the declaration disclosure. This keeps the page outline focused on usage contracts while symbols and members retain their direct anchors.</p><p>Module references include generated Markdown catalogs with the standard VitePress Markdown-include directive. Keep source examples executable, small, and independent of external datasets.</p><p>Rust sidebar API entries follow <code>_catalog/navigation.json</code>. Route namespaces, compatibility links, and subsite counterparts are defined in <code>.vitepress/routes.mjs</code>. Python contracts are authored in <code>python/api/</code>. <code>python_docs.py</code> calls <code>python_reference.py</code> to extract declarations from current Python source and <code>_cellpack.pyi</code>, without importing the extension or optional packages; training pages include the maintained programs in <code>example/</code> directly. The subsite layout, badge switcher, and breadcrumbs live in <code>.vitepress/theme/site/</code>. Navigation and sidebars are configured in <code>.vitepress/config.mjs</code>. Theme components and styles live in <code>.vitepress/theme/</code>. <code>HeroLogo.vue</code> owns the SVG timeline and accepts the page&#39;s pause state so the homepage motion control also stops its animation.</p><h2 id="read-the-docs" tabindex="-1">Read the Docs <a class="header-anchor" href="#read-the-docs" aria-label="Permalink to &quot;Read the Docs&quot;">​</a></h2><p>Use <code>docs/cellpack/.readthedocs.yaml</code> as the project&#39;s build configuration. It selects Python 3.12, Rust 1.96, and Node.js 24. Its custom build commands bootstrap the uv tool, install the locked Python and Node dependencies, and build into <code>$READTHEDOCS_OUTPUT/html</code>.</p><p>The deployment base defaults to the English Read the Docs version path. Set <code>CELLPACK_DOCS_BASE</code> explicitly for a different mount point. Local builds default to <code>/</code>.</p><ol><li>Push the source, configuration, and Python/Node/Cargo lockfiles to your Git host.</li><li>Import the repository in Read the Docs.</li><li>Select <code>docs/cellpack/.readthedocs.yaml</code> as the build configuration.</li><li>Build the intended branch and review the generated site.</li><li>Activate the release versions you want to publish.</li></ol><p>Rust and Python share this build and deployment base. The Python reference is prepared from source text without importing optional Python integrations or building another extension wheel. Each subsite keeps its own navigation and search scope. Clicking its product name returns to its home; Project home returns to <code>/</code>.</p><p>Official references: <a href="https://vuejs.github.io/vitepress/v1/" target="_blank" rel="noreferrer">VitePress</a>, <a href="https://docs.readthedocs.com/platform/stable/build-customization.html" target="_blank" rel="noreferrer">Read the Docs custom builds</a>, and <a href="https://docs.readthedocs.com/platform/stable/guides/setup/monorepo.html" target="_blank" rel="noreferrer">multiple projects in one repository</a>.</p><h2 id="website-performance" tabindex="-1">Website performance <a class="header-anchor" href="#website-performance" aria-label="Permalink to &quot;Website performance&quot;">​</a></h2><p>Keep large features behind their page or interaction boundary. API search metadata and highlighted runnable examples have separate data loaders; complete signatures and source locations load when a definition is opened. Successful details are cached, failed loads can be retried, and closing the dialog cancels an in-flight request. Shared example files and their highlighted HTML are stored once. Ordinary API pages should not fetch the example bundle or CodeMirror. The PDF reader loads its viewer styles when mounted and removes them on navigation. VitePress local search loads its index when opened. Site metadata is shared in a cacheable module, and only the two primary Latin text fonts are preloaded.</p><p><code>prepare-logo.mjs</code> derives the website&#39;s logo resources from the canonical SVGs under <code>assets/</code>. Numeric shortening preserves the parsed number sequence, and structural simplification is disabled for style- or text-sensitive input. The animated SVG runs inside a same-origin iframe with scripts disabled; the player controls its native timeline and retains a poster during loading or failure. This isolates SVG nodes from the main document&#39;s style and layout tree; it does not eliminate the SVG nodes or their memory use in the child document.</p><p>Page prefetching follows pointer hover, keyboard focus or touch intent instead of fetching every visible sidebar link. It respects data-saving connections and uses the pinned VitePress version&#39;s route-to-chunk resolver, including deployment base prefixes. Recheck that integration when upgrading VitePress.</p><p>Homepage canvas scenes allocate their backing stores near the viewport and release them offscreen or in background tabs. Cache geometry outside animation frames; update it after resizing, font loading and layout preferences change. Scenes that only depend on scroll position declare <code>continuous: false</code>, allowing them to stop drawing once their progress settles. Keep static layouts and reduced motion free of continuous scene drawing. Collapsed API sidebar groups retain their accessible control targets while creating descendants only when expanded.</p><p>Validate frontend changes against a fresh static build on an authorized worker, using an isolated output directory through <code>CELLPACK_DOCS_OUTPUT</code>. Compare cold loads with the same viewport, CPU throttling and server compression settings. Record transferred JavaScript/CSS, canvas backing-store pixels, layout reads and long tasks alongside timing measurements. Exercise scene deep links, sidebar expansion, scoped search, API quick views and PDF navigation at desktop and mobile sizes. Local browser timings describe that test environment; they are not measurements of public hosting latency.</p><h2 id="dependency-updates" tabindex="-1">Dependency updates <a class="header-anchor" href="#dependency-updates" aria-label="Permalink to &quot;Dependency updates&quot;">​</a></h2><p>Update Python dependencies through <code>uv add --project docs/cellpack ...</code>. Update frontend dependencies in this directory and commit <code>package-lock.json</code>. The guide programs have their own <code>examples/Cargo.lock</code>. Rebuild and validate after dependency or toolchain changes.</p>`,42)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
